using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize(Policy="AdminOnly")] public class UsersController:Controller {private readonly UserManager<ApplicationUser> _users;private readonly IAuditService _audit;public UsersController(UserManager<ApplicationUser> users,IAuditService audit){_users=users;_audit=audit;}public async Task<IActionResult> Index()=>View(await _users.Users.OrderBy(x=>x.FullName).ToListAsync());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Toggle(string id){var u=await _users.FindByIdAsync(id);if(u==null)return NotFound();u.IsActive=!u.IsActive;await _users.UpdateAsync(u);await _audit.WriteAsync(u.IsActive?"Activate User":"Deactivate User","User",u.Id);return RedirectToAction(nameof(Index));}}
